DASHBOARD_HTML = r'''<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>VISION // Mission Control</title>
<style>
:root{--void:#05080d;--nav:#080f17;--panel:#0b151f;--line:#1b3b49;--line-hi:#2d6574;--ink:#dceff0;--muted:#70909a;--cyan:#56e0df;--blue:#6c9dff;--lime:#8ee6b1;--amber:#ffca6b;--red:#ff6f82;--shadow:0 20px 60px #0008}
*{box-sizing:border-box}html{background:var(--void)}body{margin:0;color:var(--ink);background:radial-gradient(circle at 55% -10%,#123f4d66 0,transparent 35%),linear-gradient(120deg,#05080d,#071119 55%,#05080d);font:13px/1.5 Inter,Segoe UI,system-ui,sans-serif;min-height:100vh}body:before{content:"";position:fixed;inset:0;pointer-events:none;opacity:.18;background-image:linear-gradient(#8ee6b108 1px,transparent 1px),linear-gradient(90deg,#8ee6b108 1px,transparent 1px);background-size:44px 44px;mask-image:linear-gradient(to bottom,black,transparent 88%)}
.app{display:grid;grid-template-columns:232px 1fr;min-height:100vh}.rail{position:sticky;top:0;height:100vh;background:#060c13dd;border-right:1px solid var(--line);padding:22px 14px;display:flex;flex-direction:column;z-index:2}.logo{display:flex;align-items:center;gap:10px;padding:4px 10px 24px}.logo-mark{width:35px;height:35px;border:1px solid var(--cyan);border-radius:11px;display:grid;place-items:center;color:var(--cyan);font-weight:800;box-shadow:0 0 26px #56e0df44,inset 0 0 12px #56e0df22}.logo strong{font-size:17px;letter-spacing:.2em}.logo small{display:block;color:var(--muted);letter-spacing:.12em;font-size:8px;margin-top:1px}.nav-title{color:#41646d;font-size:9px;letter-spacing:.18em;margin:10px 12px}.nav{display:grid;gap:5px}.nav button{font:inherit;text-align:left;background:transparent;color:var(--muted);border:1px solid transparent;border-radius:8px;padding:10px 12px;cursor:pointer}.nav button.active,.nav button:hover{color:var(--cyan);background:#0d2732;border-color:#1c4d5a}.nav button span{margin-right:9px}.rail-foot{margin-top:auto;border-top:1px solid #16303b;padding:14px 10px;color:var(--muted);font-size:11px}.lock{color:var(--lime);display:flex;gap:6px;align-items:center;margin-bottom:5px}.lock i,.live-dot{width:7px;height:7px;background:var(--lime);border-radius:50%;display:inline-block;box-shadow:0 0 10px var(--lime)}
.content{min-width:0;padding:22px 28px 40px;max-width:1600px;width:100%;margin:auto}.topbar{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid var(--line);padding:4px 0 18px}.crumb{color:var(--muted);letter-spacing:.1em;text-transform:uppercase;font-size:10px}.crumb b{color:var(--cyan)}.top-actions{display:flex;align-items:center;gap:14px}.signal{display:flex;align-items:center;gap:7px;color:var(--lime);font-size:11px}.top-button{background:#0d2028;border:1px solid var(--line-hi);color:var(--cyan);border-radius:6px;padding:7px 10px;cursor:pointer;font:inherit}.hero{display:flex;justify-content:space-between;gap:24px;align-items:flex-end;padding:26px 0 18px}.hero h1{font-size:31px;line-height:1.1;letter-spacing:.03em;margin:5px 0}.hero p{color:var(--muted);margin:6px 0}.overline{color:var(--cyan);font-size:10px;letter-spacing:.22em;text-transform:uppercase}.mission-chip{border:1px solid #316a73;border-radius:999px;color:var(--cyan);padding:7px 11px;font-size:10px;letter-spacing:.08em;background:#0a2028;white-space:nowrap}
.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-bottom:15px}.metric{background:linear-gradient(135deg,#0d1c27,#09131c);border:1px solid var(--line);border-radius:10px;padding:15px;position:relative;overflow:hidden}.metric:after{content:"";position:absolute;right:-18px;bottom:-24px;width:75px;height:75px;border-radius:50%;border:1px solid #56e0df22}.metric .label{color:var(--muted);font-size:10px;letter-spacing:.12em;text-transform:uppercase}.metric strong{font-size:26px;display:block;color:var(--cyan);margin-top:4px}.metric em{font-style:normal;color:var(--lime);font-size:10px}.layout{display:grid;grid-template-columns:minmax(0,1.15fr) minmax(300px,.85fr);gap:15px}.panel{background:linear-gradient(145deg,#0d1c27ee,#08121be8);border:1px solid var(--line);border-radius:12px;box-shadow:var(--shadow);padding:17px;min-width:0}.panel-head{display:flex;align-items:center;justify-content:space-between;margin-bottom:14px}.panel-title{display:flex;align-items:center;gap:8px;color:var(--ink);font-size:12px;letter-spacing:.12em;text-transform:uppercase}.panel-title:before{content:"";width:3px;height:15px;background:var(--cyan);box-shadow:0 0 10px var(--cyan)}.panel-code{color:#416772;font:10px ui-monospace,monospace}.dispatch{grid-column:1}.composer{border:1px solid #285362;background:#07131b;border-radius:9px;padding:11px}.composer:focus-within{border-color:var(--cyan);box-shadow:0 0 0 2px #56e0df17}.composer textarea{width:100%;border:0;outline:0;resize:vertical;min-height:68px;background:transparent;color:var(--ink);font:14px/1.5 inherit}.composer textarea::placeholder{color:#53717a}.composer-foot{display:flex;justify-content:space-between;align-items:center;border-top:1px solid #173642;padding-top:9px;margin-top:5px}.hint{color:var(--muted);font-size:10px}.dispatch-btn{border:1px solid var(--cyan);background:linear-gradient(135deg,#0e4a55,#0c2b35);color:var(--cyan);border-radius:6px;padding:8px 16px;cursor:pointer;font-weight:700;letter-spacing:.08em;font-size:11px}.dispatch-btn:hover{box-shadow:0 0 18px #56e0df44}.quick{display:flex;gap:7px;flex-wrap:wrap;margin-top:10px}.quick button{font:10px inherit;color:#9ab9c0;background:#0a1821;border:1px solid #1c3c47;border-radius:5px;padding:6px 8px;cursor:pointer}.quick button:hover{border-color:var(--cyan);color:var(--cyan)}
.mission-list{margin-top:15px}.mission{border:1px solid #193843;border-radius:8px;padding:11px;margin-top:8px;background:#09161e;cursor:pointer}.mission:hover{border-color:#397985;background:#0c1d27}.mission-head{display:flex;justify-content:space-between;gap:10px}.mission-title{font-weight:600;white-space:nowrap;text-overflow:ellipsis;overflow:hidden}.mission-meta{color:var(--muted);font-size:10px;margin-top:5px}.status{font-size:9px;letter-spacing:.07em;text-transform:uppercase;border-radius:99px;padding:3px 7px;white-space:nowrap;border:1px solid #2c5c68;color:var(--cyan);background:#0c2630}.status.completed{color:var(--lime);border-color:#26714c;background:#0c2c22}.status.awaiting_approval{color:var(--amber);border-color:#785b22;background:#302510}.status.failed{color:var(--red);border-color:#743344;background:#321720}.status.running{color:var(--blue);border-color:#375e9e;background:#101f39}.result{color:#a8c6ca;white-space:pre-wrap;font-size:11px;margin-top:8px;border-top:1px solid #183640;padding-top:8px}.mission-actions{display:flex;gap:6px;margin-top:8px}.mini-btn{font:10px inherit;border:1px solid #2c5c68;background:#0b2028;color:var(--cyan);border-radius:5px;padding:4px 7px;cursor:pointer}.mini-btn.warn{color:var(--amber);border-color:#785b22;background:#302510}
.agents{grid-column:2}.agent-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:7px}.agent-card{background:#09161e;border:1px solid #1a3944;border-radius:7px;padding:10px;position:relative}.agent-card:before{content:"";position:absolute;left:0;top:10px;bottom:10px;width:2px;background:var(--cyan);box-shadow:0 0 8px var(--cyan)}.agent-card .name{font-weight:650;margin-left:6px}.agent-card .role{font-size:10px;color:var(--muted);margin:4px 0 7px 6px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.agent-card .agent-state{font-size:9px;color:var(--lime);margin-left:6px}.risk{float:right;font-size:8px;color:var(--muted);border:1px solid #294650;border-radius:99px;padding:2px 5px}.telemetry{grid-column:2}.bar-row{margin:12px 0}.bar-label{display:flex;justify-content:space-between;color:var(--muted);font-size:10px;margin-bottom:5px}.bar{height:5px;border-radius:9px;background:#102630;overflow:hidden}.bar i{display:block;height:100%;background:linear-gradient(90deg,var(--cyan),var(--blue));box-shadow:0 0 8px var(--cyan);border-radius:9px}.events{grid-column:1;height:250px;overflow:auto}.event{display:grid;grid-template-columns:46px 1fr;gap:9px;padding:8px 0;border-bottom:1px solid #102a34;font:10px ui-monospace,Consolas,monospace}.event-no{color:#3e6f7a}.event b{color:var(--cyan);font-weight:500}.event small{display:block;color:var(--muted);margin-top:2px}.memory{grid-column:2}.memory-form{display:flex;gap:7px}.memory-form input{min-width:0;flex:1;background:#07131b;border:1px solid #285362;border-radius:6px;color:var(--ink);padding:9px;font:11px inherit;outline:0}.memory-list{max-height:150px;overflow:auto;margin-top:10px}.memory-item{padding:8px 0;border-bottom:1px solid #102a34;color:#a8c6ca;font-size:11px}.empty{text-align:center;color:var(--muted);padding:24px 8px;font-size:11px}.modal{position:fixed;inset:0;background:#020509bb;display:none;place-items:center;padding:20px;z-index:5}.modal.open{display:grid}.modal-box{max-width:680px;width:100%;max-height:80vh;overflow:auto;background:#0c1a24;border:1px solid var(--line-hi);border-radius:12px;padding:20px;box-shadow:0 0 50px #000}.modal-close{float:right;background:transparent;border:0;color:var(--muted);font-size:20px;cursor:pointer}.detail-pre{white-space:pre-wrap;color:#a8c6ca;font:11px ui-monospace,monospace;background:#07131b;border:1px solid #1c3c47;border-radius:7px;padding:12px;overflow:auto}
@media(max-width:1050px){.app{grid-template-columns:74px 1fr}.rail{padding:16px 9px}.logo{justify-content:center;padding-left:0;padding-right:0}.logo strong,.logo small,.nav-title,.rail-foot{display:none}.nav button{text-align:center;font-size:18px;padding:10px}.content{padding:18px}.layout{grid-template-columns:1fr}.agents,.telemetry,.memory,.events,.dispatch{grid-column:1}}@media(max-width:620px){.app{display:block}.rail{position:relative;width:100%;height:auto;display:block;border-right:0;border-bottom:1px solid var(--line);padding:10px}.logo{justify-content:flex-start;padding:4px 6px 9px}.logo strong,.logo small{display:block}.nav{display:flex}.nav-title{display:none}.nav button{font-size:12px;flex:1}.content{padding:14px}.hero{display:block}.mission-chip{display:inline-block;margin-top:10px}.metrics{grid-template-columns:repeat(2,1fr)}.topbar{align-items:flex-start;gap:9px;flex-direction:column}.agent-grid{grid-template-columns:1fr}}
</style></head>
<body><div class="app"><aside class="rail"><div class="logo"><div class="logo-mark">V</div><div><strong>VISION</strong><small>MISSION CONTROL</small></div></div><div class="nav-title">SYSTEM</div><nav class="nav"><button class="active" onclick="scrollToId('command')"><span>⌁</span>Command</button><button onclick="scrollToId('agents-panel')"><span>◈</span>Agents</button><button onclick="scrollToId('memory-panel')"><span>▣</span>Memory</button><button onclick="scrollToId('telemetry-panel')"><span>◌</span>Telemetry</button></nav><div class="rail-foot"><div class="lock"><i></i>LOCAL / GUARDED</div><div>v0.1.0 · CORE ONLINE</div></div></aside>
<main class="content"><div class="topbar"><div class="crumb">VISION / <b>MISSION CONTROL</b></div><div class="top-actions"><div class="signal"><span class="live-dot"></span><span id="status">CONNECTING</span></div><button class="top-button" onclick="window.open('/', '_blank')">↗ LOCAL API</button></div></div><section class="hero"><div><div class="overline">Autonomous intelligence network</div><h1>Good evening. Systems are ready.</h1><p>Dispatch a mission and let specialist agents coordinate the work.</p></div><div class="mission-chip">◉ ALL CHANNELS SECURE</div></section>
<section class="metrics"><div class="metric"><div class="label">Active missions</div><strong id="active-count">—</strong><em>live queue</em></div><div class="metric"><div class="label">Completed</div><strong id="completed-count">—</strong><em>verified runs</em></div><div class="metric"><div class="label">Agent nodes</div><strong id="agent-count">—</strong><em>ready</em></div><div class="metric"><div class="label">Event sequence</div><strong id="event-count">—</strong><em>audit trail</em></div></section>
<section class="layout"><section class="panel dispatch" id="command"><div class="panel-head"><div class="panel-title">Dispatch mission</div><div class="panel-code">INPUT / 01</div></div><div class="composer"><textarea id="prompt" placeholder="Tell VISION what needs to happen… e.g. Research the latest agent frameworks and compare them."></textarea><div class="composer-foot"><span class="hint">CTRL + ENTER to dispatch · high-impact actions pause for approval</span><button class="dispatch-btn" onclick="submitTask()">DISPATCH ↗</button></div></div><div class="quick"><button onclick="quick('Check system status and available resources')">SYSTEM SCAN</button><button onclick="quick('Research the latest multi-agent AI frameworks')">DEEP RESEARCH</button><button onclick="quick('Remember that I prefer concise technical reports')">SAVE MEMORY</button><button onclick="quick('Inspect this repository and explain the test workflow')">CODE AUDIT</button></div><div class="mission-list"><div class="panel-head"><div class="panel-title">Mission queue</div><div class="panel-code" id="queue-label">0 RECORDS</div></div><div id="tasks"><div class="empty">No missions dispatched.</div></div></div></section>
<section class="panel agents" id="agents-panel"><div class="panel-head"><div class="panel-title">Agent constellation</div><div class="panel-code">NODES / READY</div></div><div class="agent-grid" id="agents"><div class="empty">Synchronizing nodes…</div></div></section><section class="panel telemetry" id="telemetry-panel"><div class="panel-head"><div class="panel-title">Runtime telemetry</div><div class="panel-code">HEALTH / NOMINAL</div></div><div class="bar-row"><div class="bar-label"><span>Coordinator availability</span><b>100%</b></div><div class="bar"><i style="width:100%"></i></div></div><div class="bar-row"><div class="bar-label"><span>Safety enforcement</span><b>ACTIVE</b></div><div class="bar"><i style="width:92%"></i></div></div><div class="bar-row"><div class="bar-label"><span>Event persistence</span><b>SQLITE</b></div><div class="bar"><i style="width:100%"></i></div></div><div class="bar-row"><div class="bar-label"><span>Model synthesis</span><b id="provider">DETERMINISTIC</b></div><div class="bar"><i id="model-bar" style="width:38%"></i></div></div></section><section class="panel events"><div class="panel-head"><div class="panel-title">Live event stream</div><div class="panel-code">EVENTS / TAIL</div></div><div id="events"><div class="empty">Waiting for events…</div></div></section><section class="panel memory" id="memory-panel"><div class="panel-head"><div class="panel-title">Memory vault</div><div class="panel-code">USER-APPROVED</div></div><div class="memory-form"><input id="memory-input" placeholder="Save a durable note…"><button class="mini-btn" onclick="saveMemory()">STORE</button></div><div class="memory-list" id="memories"><div class="empty">No stored notes.</div></div></section></section></main></div>
<div class="modal" id="modal" onclick="if(event.target===this)closeDetail()"><div class="modal-box"><button class="modal-close" onclick="closeDetail()">×</button><div class="panel-title">Mission detail</div><p class="muted" id="detail-meta"></p><div class="detail-pre" id="detail-body"></div></div></div>
<script>
let lastEvent=0;
async function api(url,options){const r=await fetch(url,options);const d=await r.json();if(!r.ok)throw Error(d.error||'Request failed');return d}
function escapeHtml(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function scrollToId(id){document.getElementById(id)?.scrollIntoView({behavior:'smooth',block:'start'})}
function quick(text){const input=document.getElementById('prompt');input.value=text;input.focus()}
function taskView(t){const action=t.status==='awaiting_approval'?`<button class="mini-btn warn" onclick="event.stopPropagation();approve('${t.id}')">APPROVE</button>`:'';return `<article class="mission" onclick="inspectTask('${t.id}')"><div class="mission-head"><div class="mission-title">${escapeHtml(t.prompt)}</div><span class="status ${escapeHtml(t.status)}">${escapeHtml(t.status.replace('_',' '))}</span></div><div class="mission-meta">${escapeHtml(t.route)} · ${escapeHtml(t.risk)} risk · ${escapeHtml(t.id.slice(0,8))} · ${escapeHtml(new Date(t.created_at).toLocaleTimeString())}</div>${t.result?`<div class="result">${escapeHtml(t.result)}</div>`:''}${t.error?`<div class="result" style="color:var(--red)">${escapeHtml(t.error)}</div>`:''}<div class="mission-actions">${action}<button class="mini-btn" onclick="event.stopPropagation();inspectTask('${t.id}')">INSPECT</button></div></article>`}
async function refresh(){try{const [overview,agents,tasks,events,memories]=await Promise.all([api('/api/overview'),api('/api/agents'),api('/api/tasks'),api('/api/events?after='+lastEvent),api('/api/memories')]);document.getElementById('status').textContent=overview.health.status.toUpperCase();document.getElementById('active-count').textContent=overview.active_tasks;document.getElementById('completed-count').textContent=overview.completed_tasks;document.getElementById('agent-count').textContent=agents.agents.length;document.getElementById('event-count').textContent=overview.event_count;document.getElementById('provider').textContent=overview.health.llm_provider.toUpperCase();document.getElementById('model-bar').style.width=overview.health.llm_provider==='deterministic'?'38%':'78%';document.getElementById('queue-label').textContent=tasks.tasks.length+' RECORDS';document.getElementById('tasks').innerHTML=tasks.tasks.length?tasks.tasks.map(taskView).join(''):'<div class="empty">No missions dispatched.</div>';document.getElementById('agents').innerHTML=agents.agents.map(a=>`<div class="agent-card"><span class="risk">${escapeHtml(a.risk_level)}</span><div class="name">${escapeHtml(a.name)}</div><div class="role">${escapeHtml(a.role)}</div><div class="agent-state">● READY</div></div>`).join('');document.getElementById('memories').innerHTML=memories.memories.length?memories.memories.map(m=>`<div class="memory-item"><b>${escapeHtml(m.kind)}</b> · ${escapeHtml(m.content)}</div>`).join(''):'<div class="empty">No stored notes.</div>';if(events.events.length){lastEvent=events.events[events.events.length-1].sequence;const box=document.getElementById('events');if(box.querySelector('.empty'))box.innerHTML='';box.innerHTML=events.events.map(e=>`<div class="event"><span class="event-no">#${e.sequence}</span><div><b>${escapeHtml(e.kind.toUpperCase())}</b> ${escapeHtml(e.message)}<small>${escapeHtml(new Date(e.created_at).toLocaleTimeString())}</small></div></div>`).join('')+box.innerHTML}}catch(e){document.getElementById('status').textContent='OFFLINE'}}
async function submitTask(){const input=document.getElementById('prompt');if(!input.value.trim())return;try{await api('/api/tasks',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({prompt:input.value})});input.value='';refresh()}catch(e){alert(e.message)}}
async function approve(id){await api('/api/tasks/'+id+'/approve',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});refresh()}
async function saveMemory(){const input=document.getElementById('memory-input');if(!input.value.trim())return;try{await api('/api/memories',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({content:input.value,kind:'dashboard_note'})});input.value='';refresh()}catch(e){alert(e.message)}}
async function inspectTask(id){try{const d=await api('/api/tasks/'+id);document.getElementById('detail-meta').textContent=d.task.route+' · '+d.task.status+' · '+d.task.id;document.getElementById('detail-body').textContent=JSON.stringify(d.task,null,2);document.getElementById('modal').classList.add('open')}catch(e){alert(e.message)}}
function closeDetail(){document.getElementById('modal').classList.remove('open')}
document.getElementById('prompt').addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key==='Enter')submitTask()});document.getElementById('memory-input').addEventListener('keydown',e=>{if(e.key==='Enter')saveMemory()});refresh();setInterval(refresh,1200);
</script></body></html>'''
